using Essco.Application.Inventory;using Essco.Application.Security;using Essco.Domain.Inventory;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc.RazorPages;namespace Essco.Web.Pages.Inventory;[Authorize(Policy=Permissions.Inventory)]public sealed class IndexModel(InventoryService service):PageModel{public IReadOnlyCollection<PhysicalInventory>Items{get;private set;}=[];public async Task OnGetAsync(CancellationToken t)=>Items=await service.ListAsync(t);}
